consumer_dma_device.source:
int mt76_npu_init(struct mt76_dev *dev, phys_addr_t phy_addr, u64 bar_bytes, int type)
{
	struct airoha_ppe_dev *ppe_dev;
	struct airoha_npu *npu;
	int err = 0;

	mutex_lock(&dev->mutex);
	if (dev->mmio.npu_irq.closing) {
		err = -ESHUTDOWN;
		goto error_unlock;
	}
	err = mt76_npu_irq_error(dev);
	if (err)
		goto error_unlock;

	npu = airoha_npu_get(dev->dev);
	if (IS_ERR(npu)) {
		request_module("airoha-npu");
		npu = airoha_npu_get(dev->dev);
	}

	if (IS_ERR(npu)) {
		err = PTR_ERR(npu);
		goto error_unlock;
	}

	ppe_dev = airoha_ppe_get_dev(dev->dev);
	if (IS_ERR(ppe_dev)) {
		request_module("airoha-eth");
		ppe_dev = airoha_ppe_get_dev(dev->dev);
	}

	if (IS_ERR(ppe_dev)) {
		err = PTR_ERR(ppe_dev);
		goto error_npu_put;
	}

	err = airoha_npu_wlan_init_reserved_memory(npu);
	if (err)
		goto error_ppe_put;
	err = airoha_npu_wlan_bind_endpoint(npu, dev->dev, phy_addr, bar_bytes, type);
	if (err)
		goto error_ppe_put;

	dev->dma_dev = npu->dev;
	dev->mmio.phy_addr = phy_addr;
	dev->mmio.npu_type = type;
	/* NPU offloading requires HW-RRO for RX packet reordering. */
	dev->hwrro_mode = is_mt7996(dev) ? MT76_HWRRO_V3 : MT76_HWRRO_V3_1;
	dev->rx_token_size = 32768;

	rcu_assign_pointer(dev->mmio.npu, npu);
	rcu_assign_pointer(dev->mmio.ppe_dev, ppe_dev);
	synchronize_rcu();

	mutex_unlock(&dev->mutex);

	return 0;

error_ppe_put:
	airoha_ppe_put_dev(ppe_dev);
error_npu_put:
	airoha_npu_put(npu);
error_unlock:
	mutex_unlock(&dev->mutex);

	return err;
}

consumer_rx_init.source:
int mt76_npu_rx_queue_init(struct mt76_dev *dev, struct mt76_queue *q)
{
	int err, irq, qid = q - &dev->q_rx[0];
	int size, index = qid - MT_RXQ_NPU0;
	struct mt76_npu_irq *state = &dev->mmio.npu_irq;
	struct airoha_npu *npu;
	unsigned long flags;
	const char *name;

	mutex_lock(&dev->mutex);

	npu = rcu_dereference_protected(dev->mmio.npu, &dev->mutex);
	if (index < 0 || index >= ARRAY_SIZE(state->line)) {
		err = -EINVAL;
		goto out;
	}
	spin_lock_irqsave(&dev->mmio.irq_lock, flags);
	err = state->closing ? -ESHUTDOWN : state->error;
	if (!err && (state->requested & BIT(index)))
		err = -EBUSY;
	spin_unlock_irqrestore(&dev->mmio.irq_lock, flags);
	if (err)
		goto out;
	if (!airoha_npu_wlan_irq_supported(npu)) {
		err = -EOPNOTSUPP;
		goto out;
	}
	irq = npu->irqs[index];
	if (irq < 0) {
		err = irq;
		goto out;
	}
	if (npu->irqs[1 - index] == irq) {
		err = -EINVAL;
		goto out;
	}

	q->flags = MT_NPU_Q_RX(index);
	size = qid == MT_RXQ_NPU1 ? NPU_RX1_DESC_NUM : NPU_RX0_DESC_NUM;
	err = dev->queue_ops->alloc(dev, q, 0, size,
				    MT76_NPU_RX_BUF_SIZE, 0);
	if (err)
		goto out;

	name = devm_kasprintf(dev->dev, GFP_KERNEL, "mt76-npu.%d", index);
	if (!name) {
		err = -ENOMEM;
		goto out;
	}

	err = mt76_napi_add(dev, qid, mt76_npu_rx_poll);
	if (err)
		goto out;
	err = devm_request_irq(dev->dev, irq, mt76_npu_irq_handler,
			       IRQF_NO_AUTOEN, name, q);
	if (err)
		goto out;

	spin_lock_irqsave(&dev->mmio.irq_lock, flags);
	state->line[index] = irq;
	state->requested |= BIT(index);
	state->blocked |= BIT(index);
	spin_unlock_irqrestore(&dev->mmio.irq_lock, flags);
	mt76_npu_fill_rx_queue(dev, q);
	if (!mt76_napi_enable(dev, qid))
		err = -ESHUTDOWN;
out:
	mutex_unlock(&dev->mutex);

	return err;
}

consumer_rx_fill.source:
int mt76_npu_fill_rx_queue(struct mt76_dev *dev, struct mt76_queue *q)
{
	int nframes = 0;

	while (q->queued < q->ndesc - 1) {
		struct airoha_npu_rx_dma_desc *desc = (void *)q->desc;
		struct mt76_queue_entry *e = &q->entry[q->head];
		struct page *page;
		int offset;

		e->buf = mt76_get_page_pool_buf(q, &offset, q->buf_size);
		if (!e->buf)
			break;

		e->dma_len[0] = SKB_WITH_OVERHEAD(q->buf_size);
		page = virt_to_head_page(e->buf);
		e->dma_addr[0] = page_pool_get_dma_addr(page) + offset;

		memset(&desc[q->head], 0, sizeof(*desc));
		desc[q->head].addr = e->dma_addr[0];

		q->head = (q->head + 1) % q->ndesc;
		q->queued++;
		nframes++;
	}

	return nframes;
}

provider_rx_event_exception.source:
int mt76_npu_alloc_rx_event(struct mt76_dev *dev, struct mt76_queue *q)
{
	int qid = is_mt7996(dev) ? MT_RXQ_TXFREE_BAND0 : MT_RXQ_MAIN_WA;
	struct airoha_npu *npu;
	dma_addr_t addr;
	void *buf;
	int err;

	BUILD_BUG_ON(sizeof(*q->desc) != 16);
	if (q != &dev->q_rx[qid] || q->flags != MT_NPU_Q_TXFREE(0))
		return -EOPNOTSUPP;
	if (q->desc || q->desc_dma)
		return -EBUSY;
	mutex_lock(&dev->mutex);
	npu = rcu_dereference_protected(dev->mmio.npu, &dev->mutex);
	if (!npu) {
		err = -ENODEV;
		goto unlock;
	}
	err = airoha_npu_wlan_alloc_rx_event(npu, dev->dev, dev->dma_dev,
					     q->ndesc, sizeof(*q->desc), &buf, &addr);
	if (!err) {
		q->desc = buf;
		q->desc_dma = addr;
	}
unlock:
	mutex_unlock(&dev->mutex);
	return err;
}

consumer_queue_allocation.source:
static int
mt76_dma_alloc_queue(struct mt76_dev *dev, struct mt76_queue *q,
		     int idx, int n_desc, int bufsize,
		     u32 ring_base)
{
	int ret, size;

	spin_lock_init(&q->lock);
	spin_lock_init(&q->cleanup_lock);

	q->regs = dev->mmio.regs + ring_base + idx * MT_RING_SIZE;
	q->ndesc = n_desc;
	q->buf_size = bufsize;
	q->hw_idx = idx;
	q->dev = dev;

	if (mt76_queue_is_wed_rro_ind(q))
		size = sizeof(struct mt76_wed_rro_desc);
	else if (mt76_queue_is_npu_tx(q))
		size = sizeof(struct airoha_npu_tx_dma_desc);
	else if (mt76_queue_is_npu_rx(q))
		size = sizeof(struct airoha_npu_rx_dma_desc);
	else
		size = sizeof(struct mt76_desc);

	ret = mt76_npu_alloc_rx_event(dev, q);
	if (ret == -EOPNOTSUPP)
		q->desc = dmam_alloc_coherent(dev->dma_dev, q->ndesc * size,
					      &q->desc_dma, GFP_KERNEL);
	else if (ret)
		return ret;
	if (!q->desc)
		return -ENOMEM;

	mt76_dma_queue_magic_cnt_init(dev, q);
	size = q->ndesc * sizeof(*q->entry);
	q->entry = devm_kzalloc(dev->dev, size, GFP_KERNEL);
	if (!q->entry)
		return -ENOMEM;

	ret = mt76_create_page_pool(dev, q);
	if (ret)
		return ret;

	mt76_npu_queue_setup(dev, q);
	ret = mt76_wed_dma_setup(dev, q, false);
	if (ret)
		return ret;

	if (mtk_wed_device_active(&dev->mmio.wed)) {
		if ((mtk_wed_get_rx_capa(&dev->mmio.wed) && mt76_queue_is_wed_rro(q)) ||
		    mt76_queue_is_wed_tx_free(q))
			return 0;
	}

	/* HW specific driver is supposed to reset brand-new EMI queues since
	 * it needs to set cpu index pointer.
	 */
	mt76_dma_queue_reset(dev, q, !mt76_queue_is_emi(q));

	return 0;
}

consumer_page_pool.source:
int mt76_create_page_pool(struct mt76_dev *dev, struct mt76_queue *q)
{
	bool is_qrx = mt76_queue_is_rx(dev, q);
	struct page_pool_params pp_params = {
		.order = 0,
		.flags = 0,
		.nid = NUMA_NO_NODE,
		.dev = dev->dma_dev,
	};
	int idx = is_qrx ? q - dev->q_rx : -1;

	/* Allocate page_pools just for rx/wed_tx_free queues */
	if (!is_qrx && !mt76_queue_is_wed_tx_free(q))
		return 0;

	switch (idx) {
	case MT_RXQ_MAIN:
	case MT_RXQ_BAND1:
	case MT_RXQ_BAND2:
	case MT_RXQ_NPU0:
	case MT_RXQ_NPU1:
		pp_params.pool_size = 256;
		break;
	default:
		pp_params.pool_size = 16;
		break;
	}

	if (mt76_is_mmio(dev)) {
		/* rely on page_pool for DMA mapping */
		pp_params.flags |= PP_FLAG_DMA_MAP | PP_FLAG_DMA_SYNC_DEV;
		pp_params.dma_dir = DMA_FROM_DEVICE;
		pp_params.max_len = PAGE_SIZE;
		pp_params.offset = 0;
		/* NAPI is available just for rx queues */
		if (idx >= 0 && idx < ARRAY_SIZE(dev->napi))
			pp_params.napi = &dev->napi[idx];
	}

	q->page_pool = page_pool_create(&pp_params);
	if (IS_ERR(q->page_pool)) {
		int err = PTR_ERR(q->page_pool);

		q->page_pool = NULL;
		return err;
	}

	return 0;
}

consumer_npu_queue_cleanup.source:
void mt76_npu_queue_cleanup(struct mt76_dev *dev, struct mt76_queue *q)
{
	spin_lock_bh(&q->lock);
	while (q->queued > 0) {
		struct mt76_queue_entry *e = &q->entry[q->tail];

		dma_sync_single_for_cpu(dev->dma_dev, e->dma_addr[0],
					e->dma_len[0],
					page_pool_get_dma_dir(q->page_pool));
		mt76_put_page_pool_buf(e->buf, false);
		q->tail = (q->tail + 1) % q->ndesc;
		q->queued--;
	}
	spin_unlock_bh(&q->lock);
}

consumer_dma_rx_cleanup.source:
static void
mt76_dma_rx_cleanup(struct mt76_dev *dev, struct mt76_queue *q)
{
	void *buf;
	bool more;

	if (!q->ndesc)
		return;

	if (mt76_queue_is_npu(q)) {
		mt76_npu_queue_cleanup(dev, q);
		return;
	}

	do {
		spin_lock_bh(&q->lock);
		buf = mt76_dma_dequeue(dev, q, true, NULL, NULL, &more, NULL);
		spin_unlock_bh(&q->lock);

		if (!buf)
			break;

		if (mtk_wed_device_active(&dev->mmio.wed) &&
		    mt76_queue_is_wed_rro(q))
			continue;

		if (mt76_npu_device_active(dev) &&
		    mt76_queue_is_wed_rro(q))
			continue;

		if (!mt76_queue_is_wed_rro_rxdmad_c(q) &&
		    !mt76_queue_is_wed_rro_ind(q))
			mt76_put_page_pool_buf(buf, false);
	} while (1);

	spin_lock_bh(&q->lock);
	if (q->rx_head) {
		dev_kfree_skb(q->rx_head);
		q->rx_head = NULL;
	}

	spin_unlock_bh(&q->lock);
}

consumer_dma_cleanup.source:
void mt76_dma_cleanup(struct mt76_dev *dev)
{
	bool tracked = dev->drv->drv_flags & MT_DRV_NAPI_LIFETIME;
	int i;

	mt76_worker_disable(&dev->tx_worker);
	if (tracked) {
		mt76_npu_shutdown_irqs(dev);
		mt76_napi_cleanup(dev);
	} else {
		napi_disable(&dev->tx_napi);
		netif_napi_del(&dev->tx_napi);
	}

	for (i = 0; i < ARRAY_SIZE(dev->phys); i++) {
		struct mt76_phy *phy = dev->phys[i];
		int j;

		if (!phy)
			continue;

		for (j = 0; j < ARRAY_SIZE(phy->q_tx); j++)
			mt76_dma_tx_cleanup(dev, phy->q_tx[j], true);
	}

	for (i = 0; i < ARRAY_SIZE(dev->q_mcu); i++)
		mt76_dma_tx_cleanup(dev, dev->q_mcu[i], true);

	mt76_for_each_q_rx(dev, i) {
		struct mt76_queue *q = &dev->q_rx[i];

		if (!tracked)
			netif_napi_del(&dev->napi[i]);
		mt76_dma_rx_cleanup(dev, q);

		page_pool_destroy(q->page_pool);
	}

	if (mtk_wed_device_active(&dev->mmio.wed))
		mtk_wed_device_detach(&dev->mmio.wed);

	if (mtk_wed_device_active(&dev->mmio.wed_hif2))
		mtk_wed_device_detach(&dev->mmio.wed_hif2);

	mt76_free_pending_txwi(dev);
	mt76_free_pending_rxwi(dev);
	if (dev->napi_dev) {
		free_netdev(dev->napi_dev);
		dev->napi_dev = NULL;
	}
	if (dev->tx_napi_dev) {
		free_netdev(dev->tx_napi_dev);
		dev->tx_napi_dev = NULL;
	}
}

radio_dma_disable.source:
static void mt7996_dma_disable(struct mt7996_dev *dev, bool reset)
{
	u32 hif1_ofs = 0;

	if (dev->hif2)
		hif1_ofs = MT_WFDMA0_PCIE1(0) - MT_WFDMA0(0);

	if (reset) {
		mt76_clear(dev, MT_WFDMA0_RST,
			   MT_WFDMA0_RST_DMASHDL_ALL_RST |
			   MT_WFDMA0_RST_LOGIC_RST);

		mt76_set(dev, MT_WFDMA0_RST,
			 MT_WFDMA0_RST_DMASHDL_ALL_RST |
			 MT_WFDMA0_RST_LOGIC_RST);

		if (dev->hif2) {
			mt76_clear(dev, MT_WFDMA0_RST + hif1_ofs,
				   MT_WFDMA0_RST_DMASHDL_ALL_RST |
				   MT_WFDMA0_RST_LOGIC_RST);

			mt76_set(dev, MT_WFDMA0_RST + hif1_ofs,
				 MT_WFDMA0_RST_DMASHDL_ALL_RST |
				 MT_WFDMA0_RST_LOGIC_RST);
		}
	}

	/* disable */
	mt76_clear(dev, MT_WFDMA0_GLO_CFG,
		   MT_WFDMA0_GLO_CFG_TX_DMA_EN |
		   MT_WFDMA0_GLO_CFG_RX_DMA_EN |
		   MT_WFDMA0_GLO_CFG_OMIT_TX_INFO |
		   MT_WFDMA0_GLO_CFG_OMIT_RX_INFO |
		   MT_WFDMA0_GLO_CFG_OMIT_RX_INFO_PFET2);

	if (dev->hif2) {
		mt76_clear(dev, MT_WFDMA0_GLO_CFG + hif1_ofs,
			   MT_WFDMA0_GLO_CFG_TX_DMA_EN |
			   MT_WFDMA0_GLO_CFG_RX_DMA_EN |
			   MT_WFDMA0_GLO_CFG_OMIT_TX_INFO |
			   MT_WFDMA0_GLO_CFG_OMIT_RX_INFO |
			   MT_WFDMA0_GLO_CFG_OMIT_RX_INFO_PFET2);
	}
}

radio_dma_cleanup.source:
void mt7996_dma_cleanup(struct mt7996_dev *dev)
{
	mt7996_dma_disable(dev, true);

	mt76_dma_cleanup(&dev->mt76);
}

cold_cleanup.source:
void mt7996_cleanup_device(struct mt7996_dev *dev)
{
	struct mt7996_phy *phy;
	bool dma_attached = !!dev->mt76.queue_ops;

	/* Probe/remove are serialized by the driver core. */
	if (dev->cleanup_started)
		return;
	dev->cleanup_started = true;
	WRITE_ONCE(dev->recovery.hw_init_done, false);

	mt7996_npu_rro_reset_close(dev);
	disable_work_sync(&dev->init_work);
	disable_work_sync(&dev->dump_work);
	disable_work_sync(&dev->wed_rro.work);
	mt7996_npu_rro_reset_join(dev);
	disable_work_sync(&dev->reset_work);
	disable_work_sync(&dev->rc_work);
	disable_delayed_work_sync(&dev->mt76.scan_work);
	mt7996_for_each_phy(dev, phy) {
		disable_delayed_work_sync(&phy->mt76->mac_work);
		if (test_bit(MT76_STATE_REGISTERED, &phy->mt76->state))
			disable_delayed_work_sync(&phy->mt76->roc_work);
	}
	mt7996_unregister_phy(mt7996_phy3(dev));
	mt7996_unregister_phy(mt7996_phy2(dev));
	mt7996_unregister_thermal(&dev->phy);
	mt76_unregister_device(&dev->mt76);
	mt76_worker_disable(&dev->mt76.tx_worker);
	mt7996_coredump_unregister(dev);
	if (dev->mt76.mcu_ops)
		mt7996_mcu_exit(dev);
	mt7996_pci_shutdown_irqs(dev);
	mt76_npu_shutdown_irqs(&dev->mt76);
	mt76_napi_cleanup(&dev->mt76);
	/* Responses can arrive until IRQ/NAPI ingress has finished. */
	skb_queue_purge(&dev->mt76.mcu.res_q);
	mt7996_tx_token_put(dev);
	if (dma_attached)
		mt7996_dma_cleanup(dev);
	mt7996_wed_rro_free(dev);
	if (dma_attached && mt7996_has_hwrro(dev) &&
	    !mtk_wed_device_active(&dev->mt76.mmio.wed))
		mt7996_rro_msdu_page_map_free(dev);
}

mcu_exit.source:
void mt7996_mcu_exit(struct mt7996_dev *dev)
{
	mt7996_mcu_restart(&dev->mt76);
	if (mt7996_firmware_state(dev, FW_STATE_FW_DOWNLOAD)) {
		dev_err(dev->mt76.dev, "Failed to exit mcu\n");
		goto out;
	}

	mt76_wr(dev, MT_TOP_LPCR_HOST_BAND(0), MT_TOP_LPCR_HOST_FW_OWN);
	if (dev->hif2)
		mt76_wr(dev, MT_TOP_LPCR_HOST_BAND(1),
			MT_TOP_LPCR_HOST_FW_OWN);
out:
	skb_queue_purge(&dev->mt76.mcu.res_q);
}

consumer_context_free.source:
void mt76_free_device(struct mt76_dev *dev)
{
	mt76_worker_teardown(&dev->tx_worker);
	if (dev->wq) {
		destroy_workqueue(dev->wq);
		dev->wq = NULL;
	}
	if (dev->drv->drv_flags & MT_DRV_NAPI_LIFETIME) {
		mt76_npu_shutdown_irqs(dev);
		mt76_napi_cleanup(dev);
	}
	mt76_npu_deinit(dev);
	ieee80211_free_hw(dev->hw);
}

consumer_provider_release.source:
void mt76_npu_deinit(struct mt76_dev *dev)
{
	struct airoha_ppe_dev *ppe_dev;
	struct airoha_npu *npu;

	if (dev->drv->drv_flags & MT_DRV_NAPI_LIFETIME) {
		mt76_npu_shutdown_irqs(dev);
		mt76_napi_cleanup(dev);
	}
	mutex_lock(&dev->mutex);

	npu = rcu_dereference_protected(dev->mmio.npu,
					lockdep_is_held(&dev->mutex));
	if (npu)
		airoha_npu_wlan_rro_close(npu, dev->dev);
	npu = rcu_replace_pointer(dev->mmio.npu, NULL,
				  lockdep_is_held(&dev->mutex));
	ppe_dev = rcu_replace_pointer(dev->mmio.ppe_dev, NULL,
				      lockdep_is_held(&dev->mutex));
	if (npu || ppe_dev)
		synchronize_rcu();

	mutex_unlock(&dev->mutex);

	mt76_npu_queue_cleanup(dev, &dev->q_rx[MT_RXQ_NPU0]);
	mt76_npu_queue_cleanup(dev, &dev->q_rx[MT_RXQ_NPU1]);

	if (npu)
		airoha_npu_put(npu);
	if (ppe_dev)
		airoha_ppe_put_dev(ppe_dev);
}

provider_retention.source:
static void airoha_npu_dma_cleanup(void *data)
{
	struct airoha_npu_dma_lifetime *life = data;
	unsigned int i;

	/* No physical retirement witness exists yet. Publication errors, detach
	 * and software parking must not release possibly device-owned mailboxes.
	 */
	if (life->exposed || life->rro) {
		mutex_lock(&airoha_npu_retained_lock);
		list_add_tail(&life->retained, &airoha_npu_retained_dma);
		mutex_unlock(&airoha_npu_retained_lock);
		dev_warn(life->dev, "retaining NPU DMA mailboxes pending retirement proof\n");
		return;
	}
	for (i = 0; i < ARRAY_SIZE(life->buffers); i++)
		if (life->buffers[i].buf)
			dma_free_coherent(life->dev, AIROHA_NPU_MBOX_SIZE,
					  life->buffers[i].buf, life->buffers[i].addr);
	for (i = 0; i < ARRAY_SIZE(life->tx_buffers); i++)
		if (life->tx_buffers[i].buf)
			dma_free_coherent(life->dev, life->tx_buffers[i].bytes,
					  life->tx_buffers[i].buf,
					  life->tx_buffers[i].addr);
	if (life->rx_event.buf)
		dma_free_coherent(life->dev, life->rx_event.bytes,
				  life->rx_event.buf, life->rx_event.addr);
	if (life->endpoint)
		put_device(life->endpoint);
	put_device(life->dev);
	kfree(life);
}

linux_managed_dma_allocation.source:
void *dmam_alloc_attrs(struct device *dev, size_t size, dma_addr_t *dma_handle,
		gfp_t gfp, unsigned long attrs)
{
	struct dma_devres *dr;
	void *vaddr;

	dr = devres_alloc(dmam_release, sizeof(*dr), gfp);
	if (!dr)
		return NULL;

	vaddr = dma_alloc_attrs(dev, size, dma_handle, gfp, attrs);
	if (!vaddr) {
		devres_free(dr);
		return NULL;
	}

	dr->vaddr = vaddr;
	dr->dma_handle = *dma_handle;
	dr->size = size;
	dr->attrs = attrs;

	devres_add(dev, dr);

	return vaddr;
}

linux_managed_dma_release.source:
static void dmam_release(struct device *dev, void *res)
{
	struct dma_devres *this = res;

	dma_free_attrs(dev, this->size, this->vaddr, this->dma_handle,
			this->attrs);
}

linux_driver_unbind.source:
static void __device_release_driver(struct device *dev, struct device *parent)
{
	struct device_driver *drv;

	drv = dev->driver;
	if (drv) {
		pm_runtime_get_sync(dev);

		while (device_links_busy(dev)) {
			__device_driver_unlock(dev, parent);

			device_links_unbind_consumers(dev);

			__device_driver_lock(dev, parent);
			/*
			 * A concurrent invocation of the same function might
			 * have released the driver successfully while this one
			 * was waiting, so check for that.
			 */
			if (dev->driver != drv) {
				pm_runtime_put(dev);
				return;
			}
		}

		driver_sysfs_remove(dev);

		bus_notify(dev, BUS_NOTIFY_UNBIND_DRIVER);

		pm_runtime_put_sync(dev);

		device_remove(dev);

		if (dev->bus && dev->bus->dma_cleanup)
			dev->bus->dma_cleanup(dev);

		device_unbind_cleanup(dev);
		device_links_driver_cleanup(dev);

		klist_remove(&dev->p->knode_driver);
		device_pm_check_callbacks(dev);

		bus_notify(dev, BUS_NOTIFY_UNBOUND_DRIVER);
		kobject_uevent(&dev->kobj, KOBJ_UNBIND);
	}
}

linux_unbind_cleanup.source:
static void device_unbind_cleanup(struct device *dev)
{
	devres_release_all(dev);
	arch_teardown_dma_ops(dev);
	kfree(dev->dma_range_map);
	dev->dma_range_map = NULL;
	device_set_driver(dev, NULL);
	dev_set_drvdata(dev, NULL);
	dev_pm_domain_detach(dev, dev->power.detach_power_off);
	if (dev->pm_domain && dev->pm_domain->dismiss)
		dev->pm_domain->dismiss(dev);
	pm_runtime_reinit(dev);
	dev_pm_set_driver_flags(dev, 0);
}

linux_page_pool_destroy.source:
void page_pool_destroy(struct page_pool *pool)
{
	if (!pool)
		return;

	if (!page_pool_put(pool))
		return;

	page_pool_disable_direct_recycling(pool);
	page_pool_free_frag(pool);

	if (!page_pool_release(pool))
		return;

	page_pool_detached(pool);
	pool->defer_start = jiffies;
	pool->defer_warn  = jiffies + DEFER_WARN_INTERVAL;

	INIT_DELAYED_WORK(&pool->release_dw, page_pool_release_retry);
	schedule_delayed_work(&pool->release_dw, DEFER_TIME);
}

linux_page_pool_release.source:
static int page_pool_release(struct page_pool *pool)
{
	bool in_softirq;
	int inflight;

	page_pool_scrub(pool);
	inflight = page_pool_inflight(pool, true);
	/* Acquire producer lock to make sure producers have exited. */
	in_softirq = page_pool_producer_lock(pool);
	page_pool_producer_unlock(pool, in_softirq);
	if (!inflight)
		__page_pool_destroy(pool);

	return inflight;
}

linux_page_pool_scrub.source:
static void page_pool_scrub(struct page_pool *pool)
{
	unsigned long id;
	void *ptr;

	page_pool_empty_alloc_cache_once(pool);
	if (!pool->destroy_cnt++ && pool->dma_map) {
		if (pool->dma_sync) {
			/* Disable page_pool_dma_sync_for_device() */
			pool->dma_sync = false;

			/* Make sure all concurrent returns that may see the old
			 * value of dma_sync (and thus perform a sync) have
			 * finished before doing the unmapping below. Skip the
			 * wait if the device doesn't actually need syncing, or
			 * if there are no outstanding mapped pages.
			 */
			if (dma_dev_need_sync(pool->p.dev) &&
			    !xa_empty(&pool->dma_mapped))
				synchronize_net();
		}

		/* No page ref, dma-unmap only. */
		xa_for_each(&pool->dma_mapped, id, ptr)
			__page_pool_unmap_netmem_dma(pool, page_to_netmem((struct page *)ptr));
	}

	/* No more consumers should exist, but producers could still
	 * be in-flight.
	 */
	page_pool_empty_ring(pool);
}

linux_pci_remove.source:
static void pci_device_remove(struct device *dev)
{
	struct pci_dev *pci_dev = to_pci_dev(dev);
	struct pci_driver *drv = pci_dev->driver;

	if (drv->remove) {
		pm_runtime_get_sync(dev);
		/*
		 * If the driver provides a .runtime_idle() callback and it has
		 * started to run already, it may continue to run in parallel
		 * with the code below, so wait until all of the runtime PM
		 * activity has completed.
		 */
		pm_runtime_barrier(dev);
		drv->remove(pci_dev);
		pm_runtime_put_noidle(dev);
	}
	pcibios_free_irq(pci_dev);
	pci_dev->driver = NULL;
	pci_iov_remove(pci_dev);

	/* Undo the runtime PM settings in local_pci_probe() */
	pm_runtime_put_sync(dev);

	/*
	 * If the device is still on, set the power state as "unknown",
	 * since it might change by the next time we load the driver.
	 */
	if (pci_dev->current_state == PCI_D0)
		pci_dev->current_state = PCI_UNKNOWN;

	/*
	 * We would love to complain here if pci_dev->is_enabled is set, that
	 * the driver should have called pci_disable_device(), but the
	 * unfortunate fact is there are too many odd BIOS and bridge setups
	 * that don't like drivers doing that all of the time.
	 * Oh well, we can dream of sane hardware when we sleep, no matter how
	 * horrible the crap we have to deal with is when we are awake...
	 */

	pci_dev_put(pci_dev);
}

linux_pci_shutdown.source:
static void pci_device_shutdown(struct device *dev)
{
	struct pci_dev *pci_dev = to_pci_dev(dev);
	struct pci_driver *drv = pci_dev->driver;

	pm_runtime_resume(dev);

	if (drv && drv->shutdown)
		drv->shutdown(pci_dev);

	/*
	 * If this is a kexec reboot, turn off Bus Master bit on the
	 * device to tell it to not continue to do DMA. Don't touch
	 * devices in D3cold or unknown states.
	 * If it is not a kexec reboot, firmware will hit the PCI
	 * devices with big hammer and stop their DMA any way.
	 */
	if (kexec_in_progress && (pci_dev->current_state <= PCI_D3hot))
		pci_clear_master(pci_dev);
}
